// Normalizar y validar el payload de la partida
const body = $input.first().json.body || $input.first().json;

const player = String(body.player || 'Rick Sanchez').trim();
const score = Number(body.score) || 0;
const level = Number(body.level) || 1;
const enemiesDefeated = Number(body.enemiesDefeated) || 0;
const livesRemaining = Number(body.livesRemaining) || 0;
const duration = Number(body.duration) || 0;
const timestamp = body.timestamp || new Date().toISOString();

return [{
  json: {
    player,
    score,
    level,
    enemiesDefeated,
    livesRemaining,
    duration,
    timestamp,
    isValid: score >= 0 && player.length > 0
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    classification: 'DIMENSION MASTER',
    tier: 'S-Rank',
    badge: '🏆 Maestro Multiversal',
    reward: 'Skins de Portal Gun Dorada',
    message: `¡Increíble desempeño, ${item.player}! Has demostrado maestría interdimensional con ${item.score} puntos.`
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    classification: 'PORTAL ROOKIE',
    tier: 'B-Rank',
    badge: '⚡ Recluta de la Ciudadela',
    reward: 'Batería de Portal Estándar',
    message: `Puntuación registrada (${item.score} pts). Sigue practicando en la Ciudadela para ascender de rango.`
  }
}];
